/* Print Preview opens the browser print preview without sending a print job. */
function printPreviewInvoice(key,id,mode,paper){if(mode==='thermal')openThermalInvoice(key,id,Number(paper)||db.settings.thermalWidth);else invoice(key,id,paper||db.settings.invoicePaperSize);let trigger=$('#modalBody .formactions');if(trigger){let note=document.createElement('p');note.className='printPreviewHelp';note.textContent='Review this invoice, then choose Print Preview to open your browser’s paper preview. Printing happens only when you confirm in that window.';trigger.before(note)}}
function addPrintPreviewButton(mode){let footer=$('#modalBody .formactions');if(!footer||footer.querySelector('[data-browser-print-preview]'))return;let button=document.createElement('button');button.type='button';button.className='btn';button.dataset.browserPrintPreview='';button.textContent='Print Preview';button.onclick=()=>{if(mode==='thermal')$('#printThermalReceipt')?.click();else printA4Invoice()};footer.prepend(button)}
const invoiceBeforePrintPreview=invoice;
invoice=function(key,id,paper){invoiceBeforePrintPreview(key,id,paper);addPrintPreviewButton('regular')};
const thermalBeforePrintPreview=openThermalInvoice;
openThermalInvoice=function(key,id,width){thermalBeforePrintPreview(key,id,width);addPrintPreviewButton('thermal')};
const settingsBeforePrintPreview=settingsPage;
settingsPage=function(){return settingsBeforePrintPreview()+`<section class="panel"><div class="panelhead"><h2>Print Preview</h2></div><div class="panelbody"><p>Preview a saved invoice on the selected paper size. Uses your saved custom layout when enabled.</p><div class="toolbar"><select id="settingsPrintPaper" aria-label="Print preview paper"><option value="A4">A4</option><option value="A5">A5</option><option value="Letter">Letter</option><option value="58">Thermal 58 mm</option><option value="80">Thermal 80 mm</option></select><button type="button" class="btn" id="settingsPrintPreview">Open Print Preview</button></div><p>The invoice opens first; click Print Preview there to check pages, margins and printer settings.</p></div></section>`};
const renderBeforePrintPreview=render;
render=function(){renderBeforePrintPreview();if(page==='settings'&&$('#settingsPrintPreview'))$('#settingsPrintPreview').onclick=()=>{let key=db.jobs.length?'jobs':db.sales.length?'sales':null;if(!key)return toast('Save a job card or sale first to preview an invoice.');let paper=$('#settingsPrintPaper').value;printPreviewInvoice(key,db[key][0].id,['58','80'].includes(paper)?'thermal':'regular',paper)}};
const designerBeforePrintPreview=openLayoutDesigner;
openLayoutDesigner=function(mode,key,id){designerBeforePrintPreview(mode,key,id);let footer=$('#modalBody .formactions');if(!footer)return;let button=document.createElement('button');button.type='button';button.className='btn';button.textContent='Print Preview';button.onclick=()=>{let form=$('#customLayoutForm');if(!form)return;try{let profile=readLayoutForm(form,mode),prior=structuredClone(db.settings.invoiceLayouts);db.settings.invoiceLayouts={...db.settings.invoiceLayouts,[mode]:profile};let billKey=key||(db.jobs.length?'jobs':db.sales.length?'sales':null),billId=id||(billKey?db[billKey][0].id:null);if(!billKey){db.settings.invoiceLayouts=prior;return toast('Save a job card or sale first to preview an invoice.')}if(mode==='thermal'){openThermalInvoice(billKey,billId,profile.width);$('#printThermalReceipt')?.click()}else{invoice(billKey,billId);printA4Invoice()}db.settings.invoiceLayouts=prior}catch(err){toast(err.message)}};footer.prepend(button)};
render();

